import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches } from '../../helpers/ui.ts';
import { skipWith, shown, searchField, hebNum } from '../_lib/app-0710.ts';
import {
  goHome, waitHuman, openCatalogPrayer, openCatalog, openZmanim, zmanimRows, button, MANUAL_WAIT,
} from '../_lib/readiness-1910.ts';
import { lessonsCard } from '../_lib/app-2110.ts';
import { saveShot,
  coldStart, prayersTabNoCrash, prayersListFromBracha, openTehilimScreen, segment, offlineBannerShown, retryShown, hasText,
  OFF_BANNER, OFF_SECTION, OFF_ZMANIM, OFF_HEB_DATE, OLD_NO_LOCATION, OLD_COLD_BLOCK,
} from '../_lib/app-2510.ts';

const CACHED_PRAYER = 'ערבית';
const UNCACHED = process.env.QA_UNCACHED_PRAYER || '';
const NIKUD_RE = '.*[\\u05B0-\\u05C7].*';
const LESSONS_LIST = 'השיעורים מוצגים';                  // S-28 «השיעורים מוצגים לפי סדר האלף־בית של שמם»

async function openChapter39() {
  await openTehilimScreen();
  await segment('תהילים');
  const f = (await searchField()) as unknown as WebdriverIO.Element;
  await f.clearValue();
  await f.setValue('39');
  if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
  await (await byText(hebNum(39))).click();
  await (await byText(`תהילים ${hebNum(39)}`)).waitForExist({ timeout: 20000 });
}
async function openLessons() {
  await openCatalog();
  await (await lessonsCard()).click();
  await (await byTextContains(LESSONS_LIST)).waitForExist({ timeout: 20000 });
}

describe('25.10 — без интернета: сохранённое содержимое, без падений (#7d0998)', function () {
  before(async function () {
    if (process.env.QA_OFFLINE_MANUAL !== '1') skipWith(this, 'сеть выключает человек — запуск с QA_OFFLINE_MANUAL=1 и человеком у телефона');
  });

  it('RD-06d С сетью: 2 холодных старта (OTA), затем открыть то, что должно сохраниться — ערבית, «שיעורי תורה», תהילים ל״ט, פרקי אבות, ברכה, «זמני תפילות» #7d0998 #48c24d61 @manual-check @prod-safe', async function () {
    this.timeout(900000);
    for (let i = 1; i <= 2; i++) await coldStart(`онлайн старт ${i}`);
    expect(await offlineBannerShown()).toBe(false);
    await prayersTabNoCrash('онлайн «תפילות»');
    await openCatalogPrayer(CACHED_PRAYER);
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 20000 });
    await openLessons();
    await openChapter39();
    await openTehilimScreen();
    await segment('פרקי אבות');
    await expect(byTextContains('משה קבל תורה')).toBeExisting({ wait: 15000 });
    await prayersListFromBracha();
    await openZmanim();
    await goHome();
  });

  it('RD-06e Сеть выключена: холодный старт ×3 → «בית» с баннером «אין חיבור לאינטרנט. מוצג מה שכבר נשמר במכשיר.» и «נסו שוב», без «בדיקת החשבון לא הסתיימה»; «תפילות» ×3 без падения F-54 AC1 #7d0998 #48c24d61 @manual-check @prod-safe', async function () {
    this.timeout(MANUAL_WAIT + 900000);
    await waitHuman('ВЫКЛЮЧИТЕ сеть (авиарежим: Wi‑Fi и сотовая выкл.), приложение не закрывать. Тест ждёт баннер «אין חיבור לאינטרנט».',
      offlineBannerShown);
    for (let i = 1; i <= 3; i++) {
      await coldStart(`офлайн старт ${i}/3`);
      expect(await shown(byTextContains(OLD_COLD_BLOCK))).toBe(false);
      await expect(byTextContains(OFF_BANNER)).toBeExisting({ wait: 15000 });
      expect(await retryShown()).toBe(true);
      if (i === 1) await saveShot('RD-06e-offline-home.png');
    }
    for (let i = 1; i <= 3; i++) await prayersTabNoCrash(`офлайн «תפילות» ${i}/3`);
  });

  it('RD-06f Офлайн: ранее открытая ערבית — текст с огласовками (не «הקטע אינו זמין כרגע.»); неоткрытая молитва — «הקטע אינו זמין כרגע.» + «נסו שוב», не бесконечная загрузка; «שיעורי תורה», תהילים ל״ט, פרקי אבות, «רשימת התפילות» из ברכה F-54 AC1 F-56 AC1 #7d0998 #48c24d61 @manual-check @prod-safe', async function () {
    this.timeout(900000);
    await openCatalogPrayer(CACHED_PRAYER);
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 20000 });
    expect(await shown(byTextContains(OFF_SECTION))).toBe(false);
    await saveShot('RD-06f-offline-arvit.png');

    if (UNCACHED) {
      await openCatalogPrayer(UNCACHED).catch(() => {});      // счётчика «N מתוך M» может не быть — ждём сообщение ниже
      await expect(byTextContains(OFF_SECTION)).toBeExisting({ wait: 60000 });   // 25.10: ~15 с
      expect(await retryShown()).toBe(true);
      await saveShot('RD-06f-offline-uncached.png');
    } else {
      console.log('[RD-06f] QA_UNCACHED_PRAYER не задан — неоткрытая молитва: @manual-check («הקטע אינו זמין כרגע.» + «נסו שוב»)');
    }

    await goHome();
    await openLessons();                                      // список уроков из кэша, без вечной загрузки
    console.log('[RD-06f] открыть ранее открытый урок — @manual-check (подписи уроков не записаны)');
    await openChapter39();
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 20000 });
    await openTehilimScreen();
    await segment('פרקי אבות');
    await expect(byTextContains('משה קבל תורה')).toBeExisting({ wait: 15000 });
    await prayersListFromBracha();
    await goHome();
  });

  it('RD-06g Офлайн «זמני תפילות» → «היום הבא»: «אין חיבור לאינטרנט, ולכן זמני היום לא נטענו» + «נסו שוב», ни одного времени, нет «לא הצלחנו לטעון את המיקום שנשמר»; еврейская дата — «התאריך העברי של היום הזה אינו זמין כרגע.» F-54 AC5 #7d0998 #48c24d61 @manual-check @prod-safe', async function () {
    this.timeout(600000);
    await openZmanim();
    await (await button('היום הבא')).click();
    await expect(byTextContains(OFF_ZMANIM)).toBeExisting({ wait: 30000 });
    expect(await retryShown()).toBe(true);
    expect(await shown(byTextContains(OLD_NO_LOCATION))).toBe(false);
    expect((await zmanimRows()).filter((r) => /^\d{1,2}:\d{2}$/.test(r.time)).length).toBe(0);
    await driver.waitUntil(async () => hasText(OFF_HEB_DATE),
      { timeout: 60000, interval: 2000, timeoutMsg: 'еврейская дата: нет «התאריך העברי של היום הזה אינו זמין כרגע.» (бесконечное «טוען תאריך עברי…»?)' });
    await saveShot('RD-06g-offline-zmanim-tomorrow.png');
    await goHome();
  });

  it('RD-06h Сеть вернулась: баннер пропал, затем холодный старт ×3 → «תפילות» без падения и без повторного входа (реджект 21.10, #1b6593) #7d0998 #48c24d61 @manual-check @prod-safe', async function () {
    this.timeout(MANUAL_WAIT + 900000);
    await waitHuman('ВКЛЮЧИТЕ сеть (выключите авиарежим). Тест ждёт, пока баннер «אין חיבור לאינטרנט» пропадёт (при необходимости нажмите «נסו שוב»).',
      async () => (await shown(byText('בית'))) && !(await offlineBannerShown()));
    await prayersTabNoCrash('сеть вернулась, тёплый «תפילות»');
    for (let i = 1; i <= 3; i++) {
      await coldStart(`онлайн после офлайна, старт ${i}/3`);
      expect(await offlineBannerShown()).toBe(false);
      await prayersTabNoCrash(`онлайн после офлайна «תפילות» ${i}/3`);
    }
    await goHome();
  });

  after(async function () {
    this.timeout(MANUAL_WAIT);
    if (process.env.QA_OFFLINE_MANUAL !== '1') return;
    if (await offlineBannerShown().catch(() => false)) {
      await waitHuman('тест закончился с выключенной сетью — ВКЛЮЧИТЕ сеть', async () => !(await offlineBannerShown()));
    }
  });
});
